#ifdef MACLOCK_COMBINED_SOURCE
static void reset_flying_toasters(ClockView &view, ScreensaverMode mode) { if (mode == ScreensaverMode::FlyingToasters) for (uint8_t i = 0; i < 7; ++i) { view.screensaver_state[i] = random(0, 10); view.screensaver_state[kToasterSpeedStateOffset + i] = random(70, 131); } }
static bool update_flying_toasters(ClockView &view, uint32_t frame) { for (uint8_t i = 0; i < 7; ++i) { const uint8_t speed = view.screensaver_state[kToasterSpeedStateOffset + i]; const uint64_t before = static_cast<uint64_t>(frame) * speed, after = static_cast<uint64_t>(frame + 1) * speed; view.screensaver_x[i] += static_cast<int16_t>(after * 2 / 100 - before * 2 / 100); view.screensaver_y[i] += (i & 1) ? static_cast<int16_t>(after / 100 - before / 100) : -static_cast<int16_t>(after / 100 - before / 100); if (view.screensaver_x[i] > kExtWidth + 56) { view.screensaver_x[i] = -56; view.screensaver_state[i] = random(0, 10); } if (view.screensaver_y[i] < -20) view.screensaver_y[i] = kExtHeight; if (view.screensaver_y[i] > kExtHeight) view.screensaver_y[i] = -20; const int x = view.screensaver_x[i], y = view.screensaver_y[i]; if (view.screensaver_toaster_atlas) draw_atlas_sprite(view, view.screensaver_toaster_atlas, view.screensaver_state[i], 64, 48, x - 8, y - 10, 56, 42, true, true, static_cast<uint8_t>(((before / 100) / 5) & 1U)); else draw_toaster(view, x, y, view.screensaver_state[i], (((before / 100) / 5) + i) & 1U); } return true; }
#endif
